import {Ecosystem,SPECIES,DAY,clamp} from './simulation.js';
import {GlobeWorld as World} from './globe.js';
import {CONTINENTS,climateAt,adaptation} from './planet.js';
import {TRAITS,patternName} from './genetics.js';
import {Soundscape} from './sound.js';
